def longest_common_prefix(iterables):
    """Yield elements of the longest common prefix among given *iterables*.

    >>> ''.join(longest_common_prefix(['abcd', 'abc', 'abf']))
    'ab'

    """
    from itertools import takewhile

    def all_equal(iterable):
        g = iter(iterable)
        return all(x == y for x, y in takewhile(lambda pair: pair[0] == pair[1], zip(g, g)))

    min_length = min(len(it) for it in iterables)
    common_prefix = tuple(next(it) for it in iterables)
    for i in range(min_length):
        if all_equal(takewhile(lambda x: x == common_prefix[i], iterables)):
            yield common_prefix[i]
        else:
            break

